import numpy as np
from numpy.linalg import lstsq
from scipy.optimize import least_squares
eps=df['eps'].values; T=df['T'].values; s=df['sigma'].values
def cols(p):
    k,m,pp,q=p
    return np.column_stack([eps**2, np.exp(-k*T)*eps**1.5, eps*T**m, eps**pp*T**q])
def resid(p):
    A=cols(p); c,_,_,_=lstsq(A,s,rcond=None); return s-A@c
best=None
for k0 in [0.1,0.2,0.3]:
  for m0 in [0,1,-1]:
    for pp0 in [0.5,1,2]:
        r=least_squares(resid,[k0,m0,pp0,0.5],max_nfev=300)
        if best is None or r.cost<best.cost: best=r
p=best.x; A=cols(p); c,_,_,_=lstsq(A,s,rcond=None)
print(np.round(p,5), c, np.sum((s-A@c)**2)/np.sum((s-s.mean())**2))

